#include <cstdio>
#include <stdexcept>

int main() {
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < -100 || n > 100) return 1;
    try {
        if (n < 0) {
            throw std::runtime_error("negative");
        }
        std::printf("%d\n", n * 2);
    } catch (const std::exception&) {
        std::printf("error\n");
    }
    return 0;
}
